        assert.equal(cz.isPendingCheckRun(cr({ status: 'in_progress' })), true);
        assert.equal(cz.isPendingCheckRun(cr({ status: 'waiting' })), true);
        assert.equal(cz.isPendingCheckRun(cr({ status: 'pending' })), true);
    });

